   {#if provider&&tab==='details'}<p class="provider-note">{providerName?`Managed by ${providerName}`:'Managed by an external media provider'}</p>{/if}
   <div class="metadata" hidden={tab!=='details'}><div><label for={`${focalDescriptionId}-filename`}>Filename</label>{@render tooltip("Why can't this be changed?",'Filename cannot be changed after upload')}<input id={`${focalDescriptionId}-filename`} disabled value={filename} /></div>
    {#if local}{#if canMove}<label>Location<button type="button" role="combobox" aria-label="Location" aria-controls={`${focalDescriptionId}-locations`} aria-expanded={locationOpen} disabled={!!busy||unavailable} onclick={()=>{locationOpen=!locationOpen;if(!locationOpen)locationSearch='';}}>{@render locationIcon(folderId)}<span dir="auto">{locationName}</span></button></label>{#if locationOpen}<div class="location-popup"><input aria-label="Search folders" placeholder="Search folders" bind:value={locationSearch} /><div id={`${focalDescriptionId}-locations`} role="listbox" aria-busy={folders?.isFetching||undefined}><button type="button" role="option" aria-selected={folderId===null} onclick={()=>{folderId=null;chosenFolder=null;locationOpen=false;locationSearch='';}}>{@render locationIcon(null)}<span dir="auto">Main library</span></button>{#each folderOptions as folder}<button type="button" role="option" aria-selected={folderId===folder.id} onclick={()=>{folderId=folder.id;chosenFolder=folder;locationOpen=false;locationSearch='';}}>{@render locationIcon(folder.id)}<span dir="auto">{folder.name}</span></button>{/each}</div><p role="status" class:sr-only={!folders?.isFetching}>{folders?.isFetching?'Loading folders...':folders?.data?`${folders.data.pages.flatMap(page=>page.items).length} ${folders.data.pages.flatMap(page=>page.items).length===1?'folder':'folders'} loaded`:''}</p>{#if folders?.isError}<div role="alert">Folders could not be loaded.<button onclick={()=>void folderObserver?.refetch()}>Retry</button></div>{/if}{#if folders?.hasNextPage}<button disabled={folders.isFetchingNextPage} onclick={()=>void folderObserver?.fetchNextPage()}>Load more folders</button>{/if}</div>{/if}{:else}<label>Location<input aria-label="Location" disabled value={selected.folderId===null?'Main library':savedFolder?.name??(savedFolderLoading||folderMissing?'Loading...':'Location unavailable')} /></label>{/if}{/if}
    {#if canEditMetadata}<div><label for={`${focalDescriptionId}-alt`}>Alt Text</label>{@render tooltip('Why is this important?','Used by screen readers and when image fails to load')}<textarea id={`${focalDescriptionId}-alt`} aria-label="Alt Text" rows="2" disabled={!!busy||unavailable} bind:value={alt}></textarea></div><label>Caption<textarea placeholder="Optional caption for display" rows="4" disabled={!!busy||unavailable} bind:value={caption}></textarea></label>{/if}
   </div>
   {#if canEditMetadata&&tab==='edit-image'}<div class="image-controls">{#if showCrop}<div role="tablist" aria-label="Image editing mode"><button type="button" role="tab" aria-selected={mode==='crop'} disabled={!!busy} onclick={()=>changeMode('crop')}>Crop</button><button type="button" role="tab" aria-selected={mode==='focal-point'} disabled={!!busy} onclick={()=>changeMode('focal-point')}>Focal point</button></div>{/if}
    {#if mode==='focal-point'}<section bind:this={previewSection} style:transform={`translateY(${previewOffset}px)`}><div class="focal-header"><h3>Preview</h3>{@render tooltip('About focal point','Move the focal point to choose what stays visible in cropped images.')}<button disabled={!!busy||!focal} onclick={()=>focal=null}>Reset</button></div><p id={focalDescriptionId} class="sr-only">Move the focal point to choose what stays visible in cropped images.</p><FocalPointPreviews src={detailPreview} fallbackSrc={detailFallback} point={focal} firstPreviewRef={firstPreview} /></section>
    {:else}<div class="crop-controls"><label>Aspect ratio<button type="button" role="combobox" aria-label="Aspect ratio" aria-controls={`${focalDescriptionId}-aspects`} aria-expanded={aspectOpen} disabled={!!busy} onclick={()=>aspectOpen=!aspectOpen}>{aspects.find(([value])=>value===aspectMode)?.[1]}</button></label>{#if aspectOpen}<div id={`${focalDescriptionId}-aspects`} role="listbox">{#each aspects as [value,label]}<button type="button" role="option" aria-selected={value===aspectMode} onclick={()=>{aspectMode=value;crop=undefined;pixels=null;cropStatus='';cropError='';aspectOpen=false;}}>{label}</button>{/each}</div>{/if}<div class="crop-output"><output aria-label="Crop output dimensions">{pixels?`${pixels.width} × ${pixels.height}`:'Loading...'}</output><button type="button" aria-label="Reset crop" disabled={!!busy||!cropChanged} onclick={clearCrop}>Reset</button></div>{#if replaceAllowed&&aspectMode!=='original'}<p>Replace original is available with the Original aspect ratio.</p>{/if}{#if cropFailed}<p role="alert">This image could not be loaded for cropping.</p>{/if}{#if cropError}<p role="alert">{cropError}</p>{/if}{#if dirty}<p>Save or discard the other changes before cropping.</p>{/if}{#if cropMime==='image/webp'}<p>Animated WebP files become still images when cropped.</p>{/if}</div>{/if}
   </div>{/if}
   {#if error}<p role="alert">{error}</p>{/if}
  </div>
  {#if tab==='used-in'}<div class="usage-column"><MediaUsedIn mediaId={selected.id} {open} {queryClient} navigationBlocked={!!busy} onEntryClick={usageClick} /></div>{/if}
 </div>
 <p class="sr-only" role="status">{cropStatus}</p><p class="sr-only" role="status">{replaceStatus}</p>
 <footer data-testid="media-detail-dialog-footer"><div>{#if embedded}<button disabled={!!busy} onclick={requestClose}>Back</button>{:else}{#if canDelete&&!cropFooter}<button disabled={!!busy||unavailable} onclick={()=>confirmKind='delete'}>{busy==='delete'?'Deleting...':'Delete'}</button>{/if}{#if canReplace&&tab==='details'}<button disabled={replaceDisabled} onclick={()=>{inspectionToken++;replacement=null;error='';replaceStatus='';replacementInput?.click();}}>Replace image</button><input class="sr-only" type="file" accept={cropMime} aria-label="Choose replacement image" tabindex="-1" disabled={replaceDisabled} bind:this={replacementInput} onchange={event=>void inspectReplacement(event)} />{/if}{/if}</div><div>{#if !embedded}<button disabled={!!busy} onclick={requestClose}>{canEdit&&(tab!=='used-in'||dirty)?'Cancel':'Close'}</button>{/if}{#if cropFooter}{#if replaceAllowed}<button disabled={cropDisabled||aspectMode!=='original'} onclick={()=>confirmKind='crop'}>Replace original</button>{/if}{#if canDuplicateCrop}<button disabled={cropDisabled} onclick={()=>void startCrop('duplicate')}>Create cropped copy</button>{/if}{:else if canEdit&&(tab!=='used-in'||dirty)}<button disabled={!dirty||!!busy||unavailable} onclick={()=>void save()}>{busy==='save'?'Saving...':'Save'}</button>{/if}</div></footer>
{/snippet}
{#if open}{#if embedded}<div class="media-detail-workspace" data-testid="media-detail-workspace" inert={confirmKind!==null} aria-hidden={confirmKind?true:undefined}>{@render workspace()}</div>{:else}<dialog bind:this={dialog} aria-label="Media details" aria-modal="true" inert={confirmKind!==null} aria-hidden={confirmKind?true:undefined} class="media-details" oncancel={event=>{event.preventDefault();if(!confirmKind)requestClose();}}>{@render workspace()}</dialog>{/if}{/if}
{#if confirmKind==='discard'}<MediaDialog label="Discard changes?" onclose={()=>{confirmKind=null;pendingEntry=null;}}><h2>Discard changes?</h2><p>Your unsaved media changes will be lost.</p><button onclick={discard}>Discard</button><button onclick={()=>{confirmKind=null;pendingEntry=null;}}>Cancel</button></MediaDialog>
{:else if confirmKind==='delete'}<MediaDialog label="Delete media?" role="alertdialog" dismissible={!busy} onclose={()=>{confirmKind=null;error='';}}><h2>Delete media?</h2><p>{provider?(providerName?`"${selected.filename}" will be deleted from ${providerName}.`:`"${selected.filename}" will be deleted from its media provider.`):`"${selected.filename}" will be permanently deleted.`}</p>{#if !provider}<aside role="note">This cannot be undone<p>Content using this media item may show a broken reference.</p></aside>{/if}{#if error}<p role="alert">{error}</p>{/if}<button disabled={!!busy} onclick={()=>void remove()}>{busy==='delete'?'Deleting...':'Delete'}</button><button disabled={!!busy} onclick={()=>{confirmKind=null;error='';}}>Cancel</button></MediaDialog>
{:else if confirmKind==='crop'||confirmKind==='replace'}<MediaDialog label="Replace original image?" role="alertdialog" dismissible={!busy} onclose={()=>{confirmKind=null;replacement=null;error='';inspectionToken++;}}><h2>Replace original image?</h2><p>Every place using this image will update to the {confirmKind==='crop'?'cropped':'selected'} version.</p><aside role="note">This cannot be undone<p>{confirmKind==='crop'?'EmDash does not keep the uncropped image.':'EmDash does not keep the previous image.'}</p></aside>{#if error}<p role="alert">{error}</p>{/if}<button disabled={!!busy} onclick={()=>{if(confirmKind==='crop')void startCrop('replace');else void replace();}}>{busy?(confirmKind==='crop'?'Replacing original...':'Replacing image...'):(confirmKind==='crop'?'Replace original':'Replace image')}</button><button disabled={!!busy} onclick={()=>{confirmKind=null;replacement=null;error='';inspectionToken++;}}>Cancel</button></MediaDialog>{/if}
<style>
 .media-details{width:min(94vw,68rem);max-height:min(88dvh,43.5rem);padding:0;border:0;border-radius:.75rem;background:white;color:inherit;overflow:hidden}.media-details[open],.media-detail-workspace{display:flex;flex-direction:column;min-width:0;min-height:0}.media-detail-workspace{height:100%;overflow:hidden}dialog::backdrop{background:#0008}header{padding:1.25rem 2rem;display:flex;gap:1rem;align-items:start;justify-content:space-between;border-bottom:1px solid #dfe3e9;flex-shrink:0}h2,h3,p{margin:0}header p{margin-top:.25rem;font-size:.875rem;color:#596374}.detail-tabs{display:flex;padding:1rem 2rem;gap:.5rem;border-bottom:1px solid #dfe3e9;flex-shrink:0}.detail-tabs button{flex:1;max-width:10rem}.detail-body{display:grid;grid-template-columns:minmax(0,1fr);min-height:0;flex:1;overflow-y:auto}.preview-column,.details-column{padding:1.5rem;min-height:0;min-width:0}.preview-column{border-bottom:1px solid #dfe3e9;display:grid;gap:1.25rem;align-content:start}.details-column{display:grid;align-content:start;gap:1.25rem}.preview-column[hidden],.details-column[hidden],.file-facts[hidden],.metadata[hidden]{display:none}.file-facts{display:grid;grid-template-columns:minmax(0,3fr) minmax(0,2fr);gap:.75rem 1.5rem;font-size:.875rem}.file-facts>div{display:flex;gap:.3rem;align-items:baseline;min-width:0}.file-url{grid-column:1/-1}.file-url>span:nth-child(2){overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.metadata,.metadata>div,label,.crop-controls{display:grid;gap:.5rem}.metadata{gap:1rem}.image-controls{display:flex;flex-direction:column;gap:1rem;min-height:0;height:100%}.image-controls>[role=tablist]{display:flex;gap:.5rem}.image-controls>[role=tablist]>button{flex:1}.focal-header,.crop-output{display:flex;align-items:center;justify-content:space-between;gap:.5rem}.non-image-preview{height:256px;display:flex;align-items:center;justify-content:center;border-radius:.75rem;background:#eef0f4;overflow:hidden}.non-image-preview video{max-width:100%;max-height:100%}.non-image-preview audio{width:100%}.non-image-preview>div{text-align:center}.non-image-preview>div>span{font-size:3rem}.usage-body{display:block;flex:1 1 auto;height:min(16rem,calc(88dvh - 12.5rem));overflow:hidden}.usage-column{padding:1.5rem;height:100%;min-height:0;box-sizing:border-box}.provider-note{padding:.75rem;background:#eef0f4;border-radius:.5rem}footer{display:flex;flex-shrink:0;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:.75rem;border-top:1px solid #dfe3e9;padding:1rem 1.5rem}footer>div{display:flex;flex-wrap:wrap;gap:.5rem}button,input,textarea{font:inherit;padding:.6rem;border:1px solid #c8ced8;border-radius:.4rem}button{cursor:pointer;background:white;color:inherit}button:disabled{cursor:default;opacity:.5}button[aria-selected=true]{background:#eef0f4}textarea{width:100%;box-sizing:border-box}input:disabled{background:#eef0f4}button[role=combobox]{text-align:start}.location-icon{width:1rem;height:1rem;flex-shrink:0;vertical-align:middle;margin-inline-end:.5rem}.location-popup{padding:.5rem;border:1px solid #c8ced8;border-radius:.4rem}.location-popup [role=listbox]{display:grid;max-height:5rem;overflow-y:auto}.location-popup [role=option]{text-align:start}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}.help{position:relative;display:inline-flex;align-items:center}.help>button{padding:0;border:0;background:transparent}.help>[role=tooltip]{position:absolute;inset-block-start:100%;z-index:20;padding:.5rem;width:14rem;color:white;background:#172032;border-radius:.4rem}aside{padding:.75rem;border-radius:.5rem;background:#feeaea}aside p{margin-top:.25rem}@media(min-width:48rem){.detail-body:not(.usage-body){grid-template-columns:minmax(0,1fr) minmax(0,1fr);overflow:hidden}.preview-column,.details-column{overflow-y:auto}.preview-column{border-bottom:0;border-inline-end:1px solid #dfe3e9}.non-image-preview{height:320px}}
</style>
